package com.example

/**
 * Curated, 100% syllabus-aligned, distinct Flashcards for Civics (පුරවැසි අධ්‍යාපනය).
 * Part 2: Categories 11 to 20 (20 distinct questions per category).
 * Strictly guarantees no repeated questions within the same category or across different categories.
 */
object FlashcardBankCivicsSetsPart2 {

  fun getCard(setNum: Int, cardNum: Int): CardContentTuple {
    val c = cardNum.coerceIn(1, 20)
    return when (setNum) {
      11 -> set11[(c - 1) % set11.size]
      12 -> set12[(c - 1) % set12.size]
      13 -> set13[(c - 1) % set13.size]
      14 -> set14[(c - 1) % set14.size]
      15 -> set15[(c - 1) % set15.size]
      16 -> set16[(c - 1) % set16.size]
      17 -> set17[(c - 1) % set17.size]
      18 -> set18[(c - 1) % set18.size]
      19 -> set19[(c - 1) % set19.size]
      20 -> set20[(c - 1) % set20.size]
      else -> set11[(c - 1) % set11.size]
    }
  }

  // --- SET 11: ඡන්ද බලය, මැතිවරණ & මහජන නියෝජනය ---
  private val set11 = listOf(
    CardContentTuple("ඡන්ද බලය (Franchise / Suffrage) යනු කුමක්ද?", "ප්‍රජාතන්ත්‍රවාදී රටක සිය නියෝජිතයින් සහ පාලකයින් තෝරාපත් කරගැනීම සඳහා පුරවැසියෙකුට හිමිවන මූලික දේශපාලන අයිතියයි.", "ජනතා පරමාධිපත්‍යය ක්‍රියාත්මක කරන ප්‍රධාන මාධ්‍යයයි.", "නියෝජිතයින් තෝරාගැනීමේ අයිතිය"),
    CardContentTuple("ශ්‍රී ලංකාවේ ඡන්දය ප්‍රකාශ කිරීමේ ඡන්ද හිමිකම් වයස් සීමාව කුමක්ද?", "වයස අවුරුදු 18 සම්පූර්ණ වීම (18 වන උපන්දිනයෙන් පසු ඡන්ද හිමි නාමලේඛනයට ඇතුළත් විය හැක).", "1959 දී ඡන්ද වයස අවුරුදු 21 සිට 18 දක්වා අඩු කරන ලදී.", "අවුරුදු 18 සම්පූර්ණ වීම"),
